import time
import random

def retry_with_backoff(fn, attempts):
    _attempts = 0
    _delay = 1  # Initial delay in seconds

    while _attempts < attempts:
        try:
            return fn()
        except Exception as e:
            _attempts += 1
            if _attempts == attempts:
                raise # Re-raise the last exception if all attempts fail
            print(f'Attempt {_attempts} failed: {e}. Retrying in {_delay} seconds...')
            time.sleep(_delay)
            _delay = min(_delay * 2 + random.uniform(0, 1), 60) # Exponential backoff with jitter, max 60 seconds

    raise Exception('Reached maximum retry attempts.') # Should not be reached if exception is re-raised on last attempt
