def flatten_dict(d, sep='.'):
    'Flattens a nested dictionary.'
    obj = {}

    def recurse(x, name=''):
        if isinstance(x, dict):
            for a, b in x.items():
                recurse(b, name + a + sep)
        else:
            obj[name[:-len(sep)]] = x

    recurse(d)
    return obj
