from functools import wraps

def lru_cache_decorator(maxsize):
    'A simple LRU cache decorator'

    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Create a unique key for the cache entry, handling both positional and keyword arguments
            key_parts = []
            if args:
                key_parts.extend(args)
            if kwargs:
                # Sort kwargs by key to ensure consistent cache key
                key_parts.extend(sorted(kwargs.items()))

            # Use a tuple for the key for immutability and hashability
            key = tuple(key_parts)

            if key in cache:
                # Move the accessed item to the end to mark it as most recently used
                cache.move_to_end(key)
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result

                if len(cache) > maxsize:
                    # Remove the least recently used item (the first one)
                    cache.popitem(last=False)
                return result

