from collections import OrderedDict
from functools import wraps

def lru_cache_decorator(maxsize):
    """
    A simple LRU cache decorator.

    Args:
        maxsize (int): The maximum number of items to store in the cache.

    Returns:
        function: A decorator that caches the results of a function.
    """
    def decorator(func):
        cache = OrderedDict()

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))  # Use frozenset for kwargs to make it hashable

            if key in cache:
                # Move the accessed item to the end to mark it as most recently used
                value = cache.pop(key)
                cache[key] = value
                return value
            else:
                value = func(*args, **kwargs)
                cache[key] = value
                if len(cache) > maxsize:
                    # Remove the least recently used item (the first one)
                    cache.popitem(last=False)
                return value
        return wrapper
    return decorator

