                new_prefix = f'{prefix}{key}{sep}' if prefix else f'{key}{sep}'
                _flatten(value, new_prefix)
        else:
            flattened_dict[prefix[:-len(sep)]] = obj

    _flatten(d)
    return flattened_dict
